#include <iostream>
#include <stdexcept>
#include <string>

enum : int { OK = 0, ERR_NULL = 1, ERR_INVALID = 2, ERR_RANGE = 3, ERR_MEMORY = 4, ERR_UNKNOWN = 5 };

extern "C" int lib_parse(const char* text, int* out)
{
    *out = std::stoi(text);
    return OK;
}

int main()
{
    int v{};
    std::cout << lib_parse("42", &v) << ' ' << v << '\n';
}
